#define len(x) (int) (x).size()
#define endl "\n"
#define int long long

using namespace std;

const int N = 3e5 + 100;
int MOD;
int fib[N];

vector <int> unfib;
int notzero = 0;

void upd(int ind, int delta) {
  notzero -= (unfib[ind] != 0);
  unfib[ind] += delta;
  if (unfib[ind] >= MOD) {
    unfib[ind] -= MOD;
  };
  notzero += (unfib[ind] != 0);
}


signed main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout.tie(nullptr);

  int n, q;
  cin >> n >> q >> MOD;

  fib[0] = fib[1] = 1;
  for (int i = 2; i < N; i++) {
    fib[i] = (fib[i - 1] + fib[i - 2]) % MOD;
  }

  vector <int> delta(n);
  for (int& i : delta) {
    cin >> i;
  }
  for (int i = 0; i < n; i++) {
    int x;
    cin >> x;
    delta[i] = (delta[i] - x + MOD) % MOD;
  }

  unfib.resize(n);
  unfib[0] = delta[0];
  if (len(unfib) >= 2) {
    unfib[1] = (delta[1] - delta[0] + MOD) % MOD;
  }
  for (int i = 2; i < n; i++) {
    unfib[i] = ((long long) delta[i] - delta[i - 1] - delta[i - 2] + MOD * 2) % MOD;
  }
  for (int i = 0; i < n; i++) {
    notzero += (unfib[i] != 0);
  }

  while (q--) {
    char c;
    int l, r;
    cin >> c >> l >> r;
    if (c == 'A') {
      upd(l - 1, 1);
      if (r != n) {
        upd(r, MOD - fib[r - l + 1]);
      }
      if (r < n - 1) {
        upd(r + 1, MOD - fib[r - l]);
      }
    } else {
      upd(l - 1, MOD - 1);
      if (r != n) {
        upd(r, fib[r - l + 1]);
      }
      if (r < n - 1) {
        upd(r + 1, fib[r - l]);
      }
    }
    if (!notzero) {
      cout << "YES" << endl;
    } else {
      cout << "NO" << endl;
    }
  }
  return 0;
}
